import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
  BILLING_PRICES as PUBLIC_PRICES,
  PRICE_DESCRIPTION,
} from "@/lib/pricing";
import { BILLING_PRICES, billingConfig } from "@/lib/billing/config";
import { billingCheckoutUrl } from "@/lib/billing/dodo";

const env = {
  DODO_PAYMENTS_ENVIRONMENT: "test_mode",
  DODO_PAYMENTS_API_KEY: "[REDACTED_SECRET]",
  DODO_PAYMENTS_WEBHOOK_KEY: "fixture-secret",
  DODO_PAYMENTS_BUSINESS_ID: "bus_fixture",
  DODO_PAID_MONTHLY_PRODUCT_ID: "pdt_fixture",
  AUTH_URL: "http://localhost:3000",
};

describe("billing configuration", () => {
  it("shares exact public prices with server product validation", () => {
    expect(BILLING_PRICES).toBe(PUBLIC_PRICES);
    expect(PUBLIC_PRICES).toEqual({ INR: 29900, USD: 599 });
    expect(PRICE_DESCRIPTION).toBe(
      "₹299/month for India; US$5.99/month globally",
    );
  });
  it("requires an explicit mode and every server-side binding", () => {
    expect(billingConfig(env).environment).toBe("test_mode");
    for (const key of Object.keys(env)) {
      expect(() => billingConfig({ ...env, [key]: "" })).toThrow();
    }
    for (const mode of ["test", undefined])
      expect(() =>
        billingConfig({ ...env, DODO_PAYMENTS_ENVIRONMENT: mode }),
      ).toThrow();
    expect(() =>
      billingConfig({
        ...env,
        DODO_PAYMENTS_BASE_URL: "https://live.dodopayments.com",
      }),
    ).toThrow();
    expect(() =>
      billingConfig({
        ...env,
        DODO_PAYMENTS_CUSTOM_HEADERS: "Authorization: other",
      }),
    ).toThrow();
  });
  it("accepts live mode only with a secure return origin", () => {
    expect(() =>
      billingConfig({ ...env, DODO_PAYMENTS_ENVIRONMENT: "live_mode" }),
    ).toThrow();
    expect(
      billingConfig({
        ...env,
        DODO_PAYMENTS_ENVIRONMENT: "live_mode",
        AUTH_URL: "https://mailloop.in",
      }).environment,
    ).toBe("live_mode");
  });
  it("uses fixed validated origins and refuses unsafe URLs", () => {
    expect(
      billingConfig({ ...env, APP_ORIGIN: "https://billing-test.example.com" })
        .origin,
    ).toBe("https://billing-test.example.com");
    for (const url of [
      "http://example.com",
      "https://u:[REDACTED_EMAIL]",
      "https://example.com/path",
      "https://example.com/?x=1",
      "javascript:alert(1)",
    ])
      expect(() => billingConfig({ ...env, AUTH_URL: url })).toThrow();
  });
  it("allows only the checkout host for the selected mode", () => {
    expect(
      billingCheckoutUrl(
        "https://test.checkout.dodopayments.com/session/cks_fixture",
        "test_mode",
      ),
    ).toContain("/session/");
    expect(
      billingCheckoutUrl(
        "https://checkout.dodopayments.com/session/cks_fixture",
        "live_mode",
      ),
    ).toContain("/session/");
    for (const url of [
      "https://checkout.dodopayments.com/session/x",
      "https://test.checkout.dodopayments.com.evil.com",
      "http://test.checkout.dodopayments.com",
      "https://u:[REDACTED_EMAIL]",
    ])
      expect(() => billingCheckoutUrl(url, "test_mode")).toThrow();
    for (const url of [
      "https://test.checkout.dodopayments.com/session/x",
      "https://checkout.dodopayments.com.evil.com/session/x",
      "http://checkout.dodopayments.com/session/x",
      "https://u:[REDACTED_EMAIL]/session/x",
    ])
      expect(() => billingCheckoutUrl(url, "live_mode")).toThrow();
  });
});

const catalog = vi.hoisted(() => ({ product: vi.fn(), localized: vi.fn() }));
vi.mock("@/lib/billing/dodo", async (original) => ({
  ...(await original<typeof import("@/lib/billing/dodo")>()),
  dodoClient: () => ({
    products: {
      retrieve: catalog.product,
      localizedPrices: { list: catalog.localized },
    },
  }),
}));
import {
  fixtureProduct,
  fixtureLocalizedPrices,
} from "./helpers/dodo-fixtures";
import { verifyBillingProduct } from "@/lib/billing/store";
describe("checkout catalog eligibility", () => {
  beforeEach(() => {
    for (const [key, value] of Object.entries(env)) vi.stubEnv(key, value);
    catalog.product.mockResolvedValue(fixtureProduct());
    catalog.localized.mockResolvedValue(fixtureLocalizedPrices());
  });
  afterEach(() => vi.unstubAllEnvs());
  it("verifies the exact monthly USD base and India country price including tax", async () => {
    await expect(verifyBillingProduct()).resolves.toMatchObject({
      product_id: "pdt_fixture",
    });
    expect(catalog.localized).toHaveBeenCalledWith("pdt_fixture");
  });
  it.each([
    { currency: "INR" },
    { price: 600 },
    { price: 800 }, // Former advertised USD price must fail new checkout validation.
    { tax_inclusive: false },
    { tax_inclusive: undefined },
    { payment_frequency_count: 2 },
    { payment_frequency_interval: "Year" },
    { subscription_period_count: 1 },
    { subscription_period_interval: "Month" },
    { trial_period_days: 3 },
    { trial_amount: 100 },
    { discount: 1 },
    { discount_bps: 1 },
    { purchasing_power_parity: true },
    { type: "usage_based_price" },
  ])("rejects price drift %j", async (change) => {
    const product = fixtureProduct();
    catalog.product.mockResolvedValue({
      ...product,
      price: { ...product.price, ...change },
    });
    await expect(verifyBillingProduct()).rejects.toMatchObject({
      code: "BILLING_PRODUCT_MISMATCH",
    });
  });
  it.each([
    { business_id: "bus_other" },
    { product_id: "pdt_other" },
    { is_recurring: false },
    { pricing_mode: "by_currency" },
    { addons: ["addon"] },
  ])("rejects product drift %j", async (change) => {
    catalog.product.mockResolvedValue({ ...fixtureProduct(), ...change });
    await expect(verifyBillingProduct()).rejects.toMatchObject({
      code: "BILLING_PRODUCT_MISMATCH",
    });
  });
  it.each([
    { amount: 29901 },
    { amount: 19900 }, // Former advertised India price must fail new checkout validation.
    { currency: "USD" },
    { country_code: "US" },
    { mode: "by_currency" },
    { product_id: "other" },
  ])("rejects country rule drift %j", async (change) => {
    catalog.localized.mockResolvedValue({
      items: [{ ...fixtureLocalizedPrices().items[0], ...change }],
    });
    await expect(verifyBillingProduct()).rejects.toMatchObject({
      code: "BILLING_PRODUCT_MISMATCH",
    });
  });
  it("rejects missing or additional country rules", async () => {
    for (const items of [
      [],
      [...fixtureLocalizedPrices().items, ...fixtureLocalizedPrices().items],
    ]) {
      catalog.localized.mockResolvedValue({ items });
      await expect(verifyBillingProduct()).rejects.toThrow();
    }
  });
});
